#!/usr/bin/env bash
# SPDX-License-Identifier: AGPL-3.0-or-later
# Generated by scripts/generate-bootstrap.py; release verifier is embedded below.
set -Eeuo pipefail
umask 077
fail() { printf '[!] %s\n' "$*" >&2; exit 1; }
step() { printf '[✓] %s\n' "$*"; }
local_release=''
yes_update=0
while (($#)); do
    case "$1" in
        --release-dir) local_release="${2:?missing release directory}"; shift 2 ;;
        --yes) yes_update=1; shift ;;
        --help|-h) printf 'SHMAX: install latest signed stable release; existing installs offer a safe update.\nOptions: --yes (approve update), --release-dir DIR (verify local signed release candidate)\n'; exit 0 ;;
        *) fail "Unknown argument: $1" ;;
    esac
done
[[ $EUID == 0 ]] || fail 'Run as root: sudo bash install.sh'
[[ $(uname -s) == Linux && -r /etc/os-release ]] || fail 'Debian 13 amd64 is required'
. /etc/os-release
[[ ${ID:-} == debian && ${VERSION_ID:-} == 13 ]] || fail 'Only Debian 13 is supported by this bootstrap'
[[ $(dpkg --print-architecture) == amd64 ]] || fail 'This bootstrap currently requires amd64'
[[ -d /run/systemd/system ]] || fail 'A running systemd host is required; containers are unsupported'
printf '\n╔══════════════════════════════════════╗\n║             SHMAX                    ║\n║       MAX ↔ Telegram Bridge          ║\n╚══════════════════════════════════════╝\n\n'
step 'Debian 13 detected; architecture: amd64'
# Inspect existing installation BEFORE installing dependencies or modifying files.
existing=0
if [[ -e /opt/shmax/.shmax-installed || -e /opt/shmax/compose.yaml ]]; then
    [[ -f /opt/shmax/compose.yaml && -f /opt/shmax/.env && -x /usr/local/bin/shmax ]] || fail 'Incomplete installation detected. Existing data is preserved; use the documented repair procedure.'
    existing=1
    if (( ! yes_update )); then
        printf 'SHMAX is installed. Safely update it while preserving configuration and authorizations? [y/N] '
        answer=''
        if ! { read -r answer </dev/tty; } 2>/dev/null; then fail 'No interactive terminal. Run sudo shmax update, or pass --yes to approve.'; fi
        [[ "$answer" == y || "$answer" == Y ]] || { step 'Update cancelled; no changes made'; exit 0; }
    fi
elif [[ -d /var/lib/shmax && -n $(ls -A /var/lib/shmax) ]]; then
    fail 'Existing SHMAX data detected without deployment. Refusing a fresh install; restore or repair the existing installation.'
fi
step 'Checking dependencies'
export DEBIAN_FRONTEND=noninteractive
apt-get update
apt-get install -y --no-install-recommends ca-certificates curl python3 openssl util-linux
stage=$(mktemp -d /var/tmp/shmax-install.XXXXXXXX)
cleanup() { rm -rf "$stage"; }
trap cleanup EXIT
# Prevent concurrent fresh installation; the updater has its own transaction lock.
exec 9>/run/lock/shmax-bootstrap.lock
flock -n 9 || fail 'Another SHMAX bootstrap is running'
python3 - "$stage" "$local_release" <<'PY'
